# GH is the root namespace for new code that is shared across domain packages in the monolith.
module GH
  autoload :Associations, "gh/associations"
  autoload :Auth, "gh/auth"
  autoload :Context, "gh/context"
  autoload :ContextBoundEnumerator, "gh/context_bound_enumerator"
  autoload :Decorator, "gh/decorator"
  autoload :Domain, "gh/domain"
  autoload :DualWriter, "gh/dual_writer"
  autoload :Errors, "gh/errors"
  autoload :Interfaces, "gh/interfaces"
  autoload :Omit, "gh/omit"
  autoload :Pagination, "gh/pagination"
  autoload :RecordTransformer, "gh/record_transformer"
  autoload :Result, "gh/result"

  OMIT = T.let(Omit.new, Omit)

  sig { returns(Context) }
  def self.context
    Context.instance
  end

  sig { returns(Auth::IdentityContext) }
  def self.identity_context
    context.identity_context
  end

  # Public: Check if a feature flag is enabled, using the domain actor if available,
  # otherwise falling back to a global vexi check.
  #
  # feature_name - The name of the feature flag to check (Symbol or String)
  # default      - The default value to return if the feature check fails (default: false)
  #
  # Returns a Boolean
  sig { params(feature_name: T.any(Symbol, String), default: T::Boolean).returns(T::Boolean) }
  def self.feature_flag_enabled?(feature_name, default: false)
    actor = identity_context.domain_actor
    if actor
      actor.feature_flag_enabled?(feature_name, default: default)
    else
      FeatureFlag.vexi.enabled?(feature_name, default: default)
    end
  end
end
